#!/usr/bin/env python3
"""For each entry line on stdin, list its citations `path:N[-M]` and the bare
`:N[-M]` after them, resolve the path among the files changed base..head, and
map each line number through the diff's hunks. Prints only citations whose
file changed."""
import re, subprocess, sys

BASE, HEAD = sys.argv[1], sys.argv[2]
changed = subprocess.run(['git', 'diff', '--name-only', BASE, HEAD], capture_output=True, text=True).stdout.split()
allfiles = subprocess.run(['git', 'ls-files'], capture_output=True, text=True).stdout.split()

def resolve(p):
    hits = [f for f in allfiles if f == p or f.endswith('/' + p)]
    return hits

hunks = {}
def get_hunks(f):
    if f not in hunks:
        out = subprocess.run(['git', 'diff', '-U0', BASE, HEAD, '--', f], capture_output=True, text=True).stdout
        hs = []
        for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', out, re.M):
            a, b, c, d = int(m[1]), int(m[2] or 1), int(m[3]), int(m[4] or 1)
            hs.append((a, b, c, d))
        hunks[f] = hs
    return hunks[f]

def mapline(f, n):
    shift = 0
    for a, b, c, d in get_hunks(f):
        start = a if b > 0 else a + 1
        if n < start:
            break
        if b > 0 and n < a + b:
            return None  # inside a changed hunk
        shift = (c + d) - (a + b) if b > 0 else (c + d) - (a + 1) + 1 - 1 + 0
        if b == 0:
            shift = d
        else:
            shift = (c + d) - (a + b)
    return n + shift

TOK = re.compile(r'`([A-Za-z0-9_./$-]+\.(?:fss|fsi|java|scala|tex|py|sh|rats|ast|test|xml))(?::(\d+)(?:-(\d+))?)?|(?<![\w`])`?:(\d+)(?:-(\d+))?')
for line in sys.stdin:
    m0 = re.match(r'- ([FP]-\d+|\d+)', line)
    key = m0[1] if m0 else '?'
    cur = None
    for m in TOK.finditer(line):
        if m[1]:
            fs = resolve(m[1])
            cur = fs[0] if len(fs) == 1 else (fs and ('AMBIG:' + ','.join(fs)) or 'NOFILE:' + m[1])
            a, b = m[2], m[3]
        else:
            a, b = m[4], m[5]
        if a is None or cur is None:
            continue
        if cur.startswith(('AMBIG', 'NOFILE')):
            print(f'{key}\t{cur}:{a}{"-"+b if b else ""}\t?')
            continue
        if cur not in changed:
            continue
        na = mapline(cur, int(a)); nb = mapline(cur, int(b)) if b else None
        print(f'{key}\t{cur}:{a}{"-"+b if b else ""}\t-> {na}{"-"+str(nb) if b else ""}')

